    # most one unclaimed intent per job, at most one active plan per job,
    # at most one migrated plan per job, and a fresh reservation only
    # once every earlier plan of the job is compensated.
    intents_by_job: dict[str, list[str]] = {}
    for apply_key, intent in intents.items():
        intents_by_job.setdefault(intent["job_id"], []).append(apply_key)
