def _light_settlement_lineage(
    anchor_reals: tuple[str, ...],
) -> tuple[dict[str, list[dict[str, Any]]], set[str]]:
    # A structural-only read of every settlement-shaped sibling, used to
    # source new rounds and to block them while a settlement is pending
    # before the intent ledger (which the full validation needs) is
    # loaded. Only well-formed settlement objects contribute; the full
    # cross-ledger validation still runs once the snapshot is assembled,
    # so a tampered ledger is rejected there.
    discovered = _discover_lineage_paths(anchor_reals, ("settlement",))
    completed: dict[str, list[dict[str, Any]]] = {}
    pending: set[str] = set()
    for real in discovered.get("settlement", ()):
        try:
            with open(real, "rb") as handle:
                data = finite_loads(handle.read().decode("utf-8"))
        except (OSError, ValueError, UnicodeDecodeError):
            continue
        if not isinstance(data, dict):
            continue
        records = data.get("records")
        if not isinstance(records, dict):
            continue
        for record in records.values():
            if not isinstance(record, dict):
                continue
            job_id = record.get("job_id")
            state = record.get("state")
            generation = record.get("generation")
            if not isinstance(job_id, str) or not job_id:
                continue
            if state == "pending":
                pending.add(job_id)
                continue
            if state not in _SETTLE_FINAL_STATES:
                continue
            if not _is_plain_int(generation) or generation < 1:
                continue
            after = record.get("after")
            at = record.get("at")
            if not isinstance(after, dict) \
                    or not _is_plain_int(at):
                continue
            completed.setdefault(job_id, []).append(record)
    return completed, pending

